fn resolve_edges(observations: Vec<Observation>, links: &[(usize, usize, f64)]) -> ResolvedDeclarations {
    let input = input(observations);
    let ids = input.observations.keys().cloned().collect::<Vec<_>>();
    let scoring = ScoringInput {
        version: 1,
        candidate_budget: 100,
        rows: ids.iter().enumerate().map(|(index, id)| input::ComparisonRow {
            key: format!("profile-{index}"),
            name: input.observations[id].name_normalized.clone().unwrap(),
            address: input.observations[id].address_normalized.clone(),
            needs_resolution: company(&input.observations[id]).is_none(),
        }).collect(),
        members: ids.iter().enumerate().map(|(index, id)| (format!("profile-{index}"), vec![id.clone()])).collect(),
    };
    let pairs = links.iter().map(|(a, b, probability)| ScoredPair {
        left: format!("profile-{a}"), right: format!("profile-{b}"), probability: *probability,
        name_level: 2, address_level: 1,
    }).collect();
    let scored = ScoredPairs::checked(pairs, serde_json::json!({"calibrated": false}), &scoring).unwrap();
    ResolvedDeclarations::from_scored(&input, &scoring, scored, "test-run").unwrap()
}
#[test]
fn indirect_competing_anchors_abstain_under_reordered_ids() {
    for ids in [[1, 2, 3, 4], [4, 1, 3, 2], [2, 4, 1, 3]] {
        let observations = ids.iter().enumerate().map(|(index, id)| observation(
            *id, Some("acme"), None, Some("Company"),
            match index { 0 => Some("00000001"), 3 => Some("00000002"), _ => None },
        )).collect::<Vec<_>>();
        let position = |role: usize| ids.iter().filter(|id| **id < ids[role]).count();
        let links = [(0, 1), (1, 2), (2, 3)].map(|(a, b)| {
            let (a, b) = (position(a), position(b));
            (a.min(b), a.max(b), 0.01)
        });
        let result = resolve_edges(observations, &links);
        let unanchored = result.observations.iter().filter(|row| matches!(row.identity_basis, IdentityBasis::DonorNameLink)).collect::<Vec<_>>();
